// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPermanentMarker = makeLoadFont('PermanentMarker');
import { evolvePath } from "@remotion/paths";

// Module-level font loading for the marker effect
const { fontFamily: markerFamily } = loadPermanentMarker();



export type LineGraphProps = Record<string, any>;

const LineGraph: React.FC<LineGraphProps> = ({
  backgroundColor = "#f8fafc",
  transparentBackground = false,
  durationInSeconds = 5,
  title = "Growth Trend",
  yAxisTopLabel = "$100k",
  yAxisBottomLabel = "$0",
  xAxisStartLabel = "Jan",
  xAxisEndLabel = "Dec",
  lineColor = "#2563eb",
  axisColor = "#1e293b",
  markerStrokeWidth = 14,
  showGrid = true,
  gridColor = "#cbd5e1",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Layout Calculations
  const graphWidth = width * 0.75;
  const graphHeight = height * 0.55;
  const offsetX = (width - graphWidth) / 2;
  const offsetY = height * 0.28;

  // Pre-defined up-trend points (normalized 0-1)
  const normalizedPoints = [
    { x: 0.0, y: 0.90 },
    { x: 0.20, y: 0.75 },
    { x: 0.35, y: 0.82 },
    { x: 0.50, y: 0.50 },
    { x: 0.70, y: 0.35 },
    { x: 0.85, y: 0.40 },
    { x: 1.0, y: 0.10 },
  ];

  // Map to pixel coordinates
  const svgPoints = normalizedPoints.map(p => ({
    x: p.x * graphWidth,
    y: p.y * graphHeight,
  }));

  // Construct main SVG Path
  const lineD = `M ${svgPoints[0].x} ${svgPoints[0].y} ` + svgPoints.slice(1).map(p => `L ${p.x} ${p.y}`).join(" ");

  // Construct Arrow Head at the end of the line
  const lastPoint = svgPoints[svgPoints.length - 1];
  const prevPoint = svgPoints[svgPoints.length - 2];
  const dx = lastPoint.x - prevPoint.x;
  const dy = lastPoint.y - prevPoint.y;
  const angle = Math.atan2(dy, dx);
  const arrowSize = markerStrokeWidth * 3;
  const arrowAngle1 = angle - Math.PI / 7;
  const arrowAngle2 = angle + Math.PI / 7;
  const p1 = {
    x: lastPoint.x - arrowSize * Math.cos(arrowAngle1),
    y: lastPoint.y - arrowSize * Math.sin(arrowAngle1)
  };
  const p2 = {
    x: lastPoint.x - arrowSize * Math.cos(arrowAngle2),
    y: lastPoint.y - arrowSize * Math.sin(arrowAngle2)
  };
  const arrowD = `M ${p1.x} ${p1.y} L ${lastPoint.x} ${lastPoint.y} L ${p2.x} ${p2.y}`;

  // Axes and Grid Paths
  const xAxisD = `M 0 ${graphHeight} L ${graphWidth} ${graphHeight}`;
  const yAxisD = `M 0 ${graphHeight} L 0 0`;
  const numGridLines = 5;
  const gridLines = Array.from({ length: numGridLines }).map((_, i) => {
    const y = (i / (numGridLines - 1)) * graphHeight;
    return `M 0 ${y} L ${graphWidth} ${y}`;
  });

  // Animation Timings
  const titleStart = 0;
  const axisStart = 10;
  const gridStart = 20;
  const lineStart = 30;
  const arrowStart = 90;

  // Interpolations
  const titleOpacity = interpolate(frame, [titleStart, titleStart + 20], [0, 1], { extrapolateRight: "clamp" });
  const titleYOffset = interpolate(frame, [titleStart, titleStart + 20], [30, 0], { extrapolateRight: "clamp" });

  const axisProgress = interpolate(frame, [axisStart, axisStart + 20], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const labelOpacity = interpolate(frame, [axisStart + 15, axisStart + 35], [0, 1], { extrapolateRight: "clamp" });

  const gridOpacity = interpolate(frame, [gridStart, gridStart + 20], [0, 0.4], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  
  const lineProgress = interpolate(frame, [lineStart, lineStart + 60], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const arrowProgress = interpolate(frame, [arrowStart, arrowStart + 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  // Path Evolutions
  const { strokeDasharray: xDash, strokeDashoffset: xOffset } = evolvePath(axisProgress, xAxisD);
  const { strokeDasharray: yDash, strokeDashoffset: yOffset } = evolvePath(axisProgress, yAxisD);
  const { strokeDasharray: lineDash, strokeDashoffset: lineOffset } = evolvePath(lineProgress, lineD);
  const { strokeDasharray: arrowDash, strokeDashoffset: arrowOffset } = evolvePath(arrowProgress, arrowD);

  // Parser safe opacity booleans for pure shapes
  const lineVisible = lineProgress > 0.001;
  const arrowVisible = arrowProgress > 0.001;
  const axesVisible = axisProgress > 0.001;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Title */}
      <div style={{
        position: 'absolute',
        top: height * 0.12,
        left: '10%',
        width: '80%',
        textAlign: 'center',
        fontSize: 72,
        color: axisColor,
        opacity: titleOpacity,
        transform: `translateY(${titleYOffset}px)`,
        fontFamily: markerFamily,
        transition: "none"
      }}>
        {title}
      </div>

      {/* Axis Labels */}
      <div style={{
        position: 'absolute',
        left: offsetX - 120,
        top: offsetY - 25,
        width: 100,
        textAlign: 'right',
        fontFamily: markerFamily,
        fontSize: 36,
        color: axisColor,
        opacity: labelOpacity,
        transition: "none"
      }}>
        {yAxisTopLabel}
      </div>
      <div style={{
        position: 'absolute',
        left: offsetX - 120,
        top: offsetY + graphHeight - 25,
        width: 100,
        textAlign: 'right',
        fontFamily: markerFamily,
        fontSize: 36,
        color: axisColor,
        opacity: labelOpacity,
        transition: "none"
      }}>
        {yAxisBottomLabel}
      </div>
      <div style={{
        position: 'absolute',
        left: offsetX,
        top: offsetY + graphHeight + 15,
        fontFamily: markerFamily,
        fontSize: 36,
        color: axisColor,
        opacity: labelOpacity,
        transition: "none"
      }}>
        {xAxisStartLabel}
      </div>
      <div style={{
        position: 'absolute',
        left: offsetX + graphWidth - 100,
        top: offsetY + graphHeight + 15,
        width: 100,
        textAlign: 'right',
        fontFamily: markerFamily,
        fontSize: 36,
        color: axisColor,
        opacity: labelOpacity,
        transition: "none"
      }}>
        {xAxisEndLabel}
      </div>

      {/* Main SVG Canvas */}
      <svg 
        width={graphWidth} 
        height={graphHeight} 
        style={{ 
          position: 'absolute', 
          left: offsetX, 
          top: offsetY, 
          overflow: 'visible',
          transition: "none"
        }}
      >
        {/* Grid Lines */}
        {showGrid && gridLines.map((line, i) => (
          <path 
            key={`grid-${i}`} 
            d={line} 
            stroke={gridColor} 
            strokeWidth={3} 
            opacity={gridOpacity} 
            strokeDasharray="12, 16" 
            strokeLinecap="round" 
            style={{ transition: "none" }}
          />
        ))}

        {/* Axes */}
        <path 
          d={yAxisD} 
          stroke={axisColor} 
          strokeWidth={6} 
          strokeLinecap="round" 
          strokeDasharray={yDash} 
          strokeDashoffset={yOffset} 
          opacity={axesVisible ? 1 : 0}
          style={{ transition: "none" }}
        />
        <path 
          d={xAxisD} 
          stroke={axisColor} 
          strokeWidth={6} 
          strokeLinecap="round" 
          strokeDasharray={xDash} 
          strokeDashoffset={xOffset} 
          opacity={axesVisible ? 1 : 0}
          style={{ transition: "none" }}
        />

        {/* Main Trend Line */}
        <path 
          d={lineD} 
          stroke={lineColor} 
          strokeWidth={markerStrokeWidth} 
          strokeLinecap="round" 
          strokeLinejoin="round" 
          strokeDasharray={lineDash} 
          strokeDashoffset={lineOffset} 
          fill="none"
          opacity={lineVisible ? 1 : 0}
          style={{
            transition: "none",
            filter: "drop-shadow(0px 8px 12px rgba(0,0,0,0.15))"
          }}
        />

        {/* Trend Arrow Head */}
        <path 
          d={arrowD} 
          stroke={lineColor} 
          strokeWidth={markerStrokeWidth} 
          strokeLinecap="round" 
          strokeLinejoin="round" 
          strokeDasharray={arrowDash} 
          strokeDashoffset={arrowOffset} 
          fill="none"
          opacity={arrowVisible ? 1 : 0}
          style={{
            transition: "none",
            filter: "drop-shadow(0px 8px 12px rgba(0,0,0,0.15))"
          }}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default LineGraph;